27: function startGame(){clearInterval(timer);game={active:true,seed:rand(10000,99999),stage:0,biome:null,enemy:null,hp:100,maxHp:100,attack:12,armor:2,potions:2,relics:[],coins:0,level:1,abilityCd:0,paused:false,turn:0,log:'',fx:0,auto:true};$('runTag').textContent='EXPEDITION · '+game.seed;$('seedText').textContent='SEED · '+game.seed;showStage(0);setLog('The road stirs. Your blade answers.');updateUI();$('overlay').classList.add('hidden');timer=setInterval(tick,1050)}
28: function showStage(stage){game.stage=stage;let options=stage===0?first:stage===1?second:['castle'];let idx=rand(0,options.length-1), key=options[idx];game.biome=key;let data=biomes[key];let hp=data.hp+Math.max(0,stage-1)*8;game.enemy={name:data.enemy,hp,maxHp:hp,atk:data.atk+(stage===2?1:0),icon:data.enemyIcon};$('regionLabel').textContent=stage===2?'THE LAST REALM':stage===1?'THE SECOND REALM':'THE FIRST REALM';$('stageCount').textContent='✦ '+(stage+1)+' / 3';$('biomeIcon').textContent=data.icon;$('biomeName').textContent=data.name;$('biomeNote').textContent=data.weather;$('battleBanner').textContent=stage===2?'FINAL ENCOUNTER':'AUTO-BATTLE · '+(stage+1)+' OF 3';$('enemyName').innerHTML='☠ &nbsp;'+data.enemy.toUpperCase();$('enemyLevel').textContent=stage===2?'BOSS':'LV. '+(stage+1);$('enemyStatus').textContent=stage===2?'The last king waits':'Hostile';$('routeNote').textContent=stage===2?'The ruined castle is always the last stop. No one knows what comes after.':'The terrain changes with every run. No two paths are alike.';updateRoute();drawScene();setLog(stage===2?'Castle Mourning rises from the fog. The Hollow King sees you.':`${data.enemy} blocks the way through ${data.name}.`);updateUI()}
