30: function tick(){if(!game.active||game.paused||!game.enemy||game.enemy.hp<=0)return;game.turn++;if(game.abilityCd>0)game.abilityCd--;let damage=game.attack+rand(-2,3);game.enemy.hp=Math.max(0,game.enemy.hp-damage);game.fx=1;setLog(`You strike ${game.enemy.name} for ${damage} damage.`);playTone(300,0.07);updateUI();if(game.enemy.hp<=0){setTimeout(victory,700);return}setTimeout(()=>{if(!game.active||game.paused||!game.enemy||game.enemy.hp<=0)return;let raw=game.enemy.atk+rand(-2,2),hit=Math.max(1,raw-game.armor);game.hp=Math.max(0,game.hp-hit);game.fx=-1;setLog(`${game.enemy.name} hits you for ${hit} damage${game.armor?` (${game.armor} absorbed)`:''}.`);playTone(110,0.09);updateUI();if(game.hp<=0)setTimeout(defeat,700)},430)}
31: function useAbility(){if(!game.active||game.paused||!game.enemy||game.enemy.hp<=0||game.abilityCd>0)return;let damage=Math.round(game.attack*1.8)+rand(2,5);game.enemy.hp=Math.max(0,game.enemy.hp-damage);game.abilityCd=3;game.fx=1;setLog(`Ember Slash tears through ${game.enemy.name} for ${damage} damage!`);playTone(480,0.11);updateUI();if(game.enemy.hp<=0)setTimeout(victory,650)}
32: function usePotion(){if(!game.active||!game.potions||game.hp>=game.maxHp)return;let healed=Math.min(32,game.maxHp-game.hp);game.hp+=healed;game.potions--;setLog(`You drink a field tonic and recover ${healed} vitality.`);playTone(620,0.13);updateUI()}
33: function toggleAuto(){game.paused=!game.paused;$('autoBtn').classList.toggle('active',!game.paused);$('autoBtn').setAttribute('aria-pressed',String(!game.paused));$('autoLabel').innerHTML=game.paused?'▶ &nbsp; RESUME':'Ⅱ &nbsp; AUTO';$('turnLabel').textContent=game.paused?'PAUSED':'AUTO-PLAYING';if(!game.paused&&game.active)setLog('The battle resumes.')}
34: function victory(){if(!game.active)return;game.active=false;game.coins+=12+game.stage*5;updateUI();if(game.stage===2){clearInterval(timer);showEnding(true);return}showReward()}
35: function showReward(){let pool=[...relics].sort(()=>Math.random()-.5).slice(0,3);let offers=pool.map((r,i)=>`<button class="choice-card" data-choice="${i}"><span class="choice-glyph">${r.glyph}</span><span class="choice-copy"><span class="choice-name">${r.name}</span><span class="choice-desc">${r.desc}</span></span><span class="choice-plus">${r.bonus}</span></button>`).join('');let heal=Math.min(20,game.maxHp-game.hp);$('modal').innerHTML=`<div class="modal-kicker">✦ &nbsp;REALM ${game.stage+1} CLEARED</div><h1>A small light<br>in the dark.</h1><p>${game.enemy.name} falls. You gather <b style="color:var(--gold)"> ${12+game.stage*5} shards</b> from the remains. Choose one relic for the road ahead${heal?` — and recover ${heal} vitality`:''}.</p><div class="choice-list">${offers}</div><div class="modal-buttons"><button class="secondary-btn" id="skipReward">Leave it behind</button></div>`;$('overlay').classList.remove('hidden');$('modal').querySelectorAll('[data-choice]').forEach(btn=>btn.onclick=()=>{let relic=pool[Number(btn.dataset.choice)];relic.apply(game);game.relics.push(relic);advance(heal,`You claim ${relic.name}. ${relic.bonus}.`)});$('skipReward').onclick=()=>advance(heal,'You leave the relics behind and press on.')}
36: function advance(heal,msg){$('overlay').classList.add('hidden');game.hp=Math.min(game.maxHp,game.hp+heal);if(game.stage===0)game.previous0=game.biome;if(game.stage===1)game.previous1=game.biome;game.stage++;game.active=true;showStage(game.stage);setLog(msg);updateUI()}
37: function defeat(){if(!game.active)return;game.active=false;clearInterval(timer);showEnding(false)}
38: function showEnding(won){$('modal').innerHTML=won?`<div class="modal-kicker">✦ &nbsp;THE END OF THE ROAD</div><h1>The last ember<br>still burns.</h1><p>The Hollow King is no more. Through cave, wilds, and ruin, you carried the light. The realm will remember Rook.</p><p style="color:var(--gold);font:10px var(--mono);letter-spacing:.1em">RUN ${game.seed} &nbsp;·&nbsp; ${game.relics.length} RELICS &nbsp;·&nbsp; ${game.coins} SHARDS</p><div class="modal-buttons"><button class="primary-btn" id="againBtn">Begin another journey →</button></div>`:`<div class="modal-kicker">✦ &nbsp;THE ROAD GOES QUIET</div><h1>Even embers<br>fade to ash.</h1><p>Rook's journey ends in ${game.biome?biomes[game.biome].name:'the wilds'}. Another wanderer may yet make it through.</p><p style="color:var(--gold);font:10px var(--mono);letter-spacing:.1em">RUN ${game.seed} &nbsp;·&nbsp; REALMS REACHED ${game.stage+1}</p><div class="modal-buttons"><button class="primary-btn" id="againBtn">Rise and try again →</button></div>`;$('overlay').classList.remove('hidden');$('againBtn').onclick=startGame;setLog(won?'The Hollow King is gone. The ash settles.':'Your light has gone out.')}
39: function updateUI(){let hpPct=game.maxHp?Math.max(0,game.hp/game.maxHp*100):0,ep=game.enemy?Math.max(0,game.enemy.hp/game.enemy.maxHp*100):0;$('playerHpText').textContent=`${game.hp} / ${game.maxHp}`;$('playerHpBar').style.width=hpPct+'%';$('enemyHpText').textContent=game.enemy?`${game.enemy.hp} / ${game.enemy.maxHp}`:'— / —';$('enemyHpBar').style.width=ep+'%';$('playerPower').textContent='ATK '+game.attack;$('playerLevel').textContent='LV. '+game.level;$('statAttack').textContent=game.attack;$('statArmor').textContent=game.armor;$('statRelics').textContent=game.relics.length+' / 3';$('coinCount').textContent='◈ '+game.coins;$('potionCount').textContent='× '+game.potions;$('packLabel').textContent=game.potions+' TONIC'+(game.potions===1?'':'S');$('playerStatus').textContent=game.hp<35?'Wounded':game.active?'Fighting':'Ready for the road';$('enemyPower').textContent=game.enemy?'ATK '+game.enemy.atk:'ATK —';$('abilityBtn').disabled=!game.active||game.paused||game.abilityCd>0||!game.enemy||game.enemy.hp<=0;$('abilitySub').textContent=game.abilityCd>0?`Recharges · ${game.abilityCd} turns`:'Powerful strike · ready';$('potionBtn').disabled=!game.active||!game.potions||game.hp>=game.maxHp;$('turnLabel').textContent=game.active?(game.paused?'PAUSED':'AUTO-PLAYING'):'PAUSED';let items=[{glyph:'⚔',title:'Old iron blade'},...game.relics.map(r=>({glyph:r.glyph,title:r.name})),...Array(Math.max(0,2-game.relics.length)).fill({glyph:'◈',title:'Traveler’s charm'})].slice(0,3);$('inventory').innerHTML=items.map((it,i)=>`<div class="inventory-item" title="${it.title}">${it.glyph}${i>0&&i<=game.relics.length?'<small>✦</small>':''}</div>`).join('')}

